files.content:
body {
  margin: 0;
  overflow: hidden;
  background-color: #000;
  background-image: url(../images/stars.jpg);
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
}

.planets {
  position: relative;
  max-inline-size: 850px;
  min-block-size: 100dvb;
  margin: 0 auto;
}

.planets__item {
  position: absolute;
  inline-size: 50%;
  border-radius: 50%;
  inset-inline-start: 50%;
  inset-block-start: 50%;
  aspect-ratio: 1 / 1;
}

.planets__item_type_earth {
  /* Перепишите свойство transform на свойство translate */
  translate: -50% -50%;
}

.planets__item_type_moon {
  display: flex;
  justify-content: center;
  align-items: center;
  inline-size: 75%;
  outline: 1px solid rgb(255 255 255 / 0.25);
  animation: moon 25s linear infinite;
}

.planet {
  display: block;
  max-inline-size: 100%;
  border-radius: 50%;
}

.planet_type_moon {
  position: absolute;

  /* Перепишите свойство transform на отдельные свойства translate и scale */

  inset-inline-start: 0;
  translate: -50%;
  scale: 0.15;
}

@keyframes moon {
  from {
    transform:
      translateX(-50%)
      translateY(-50%)
      rotate(0);
  }

  to {
    transform:
      translateX(-50%)
      translateY(-50%)
      rotate(1turn);
  }
}
